45	/**
46	 * Filters that belong to finding-groups but are NOT valid for the
47	 * finding-group resources sub-endpoint. These must be stripped before
48	 * calling the resources API to avoid empty results.
49	 */
50	const FINDING_GROUP_RESOURCE_UNSUPPORTED_FILTERS: FilterParam[] = [
51	  "filter[service__in]",
52	  "filter[scan__in]",
53	  "filter[scan_id]",
54	  "filter[scan_id__in]",
55	];
56	
57	function normalizeFindingGroupResourceFilters(
58	  filters: Record<string, string | string[] | undefined>,
59	): Record<string, string | string[] | undefined> {
60	  const normalized = Object.fromEntries(
61	    Object.entries(filters).filter(
62	      ([key]) =>
63	        !FINDING_GROUP_RESOURCE_UNSUPPORTED_FILTERS.includes(
64	          key as FilterParam,
65	        ),
66	    ),
67	  );
68	
69	  const exactStatusFilter = normalized["filter[status]"];
70	
71	  if (exactStatusFilter !== undefined) {
72	    delete normalized["filter[status__in]"];
73	    return normalized;
74	  }
75	
76	  const statusValues = splitCsvFilterValues(normalized["filter[status__in]"]);
77	  if (statusValues.length === 1) {
78	    normalized["filter[status]"] = statusValues[0];
79	    delete normalized["filter[status__in]"];
80	  }
81	
82	  return normalized;
83	}
