 * Centralised sort tokens and presets for the findings surfaces.
 *
 * This module is intentionally free of any server-only code (no auth, no
 * `fetch`) so that action files and client components can import the tokens
 * through the `@/lib` barrel without pulling in authentication helpers.
 *
 * There are two distinct families of sort tokens because the two backend
 * shapes order their columns differently:
 *
 *   Family A — plain findings. Status/severity are Postgres ENUM columns whose
 *   natural ascending order already puts FAIL / critical first, so these tokens
 *   never carry a minus prefix for `status`/`severity`.
 *
 *   Family B — finding-groups. Status/severity/delta are integer-weighted
 *   computed columns, so descending order is required to surface
 *   FAIL / critical / new results first; these tokens always carry a minus
 *   prefix.
 */

// -----------------------------------------------------------------------------
// Family A — plain findings (Postgres ENUM, ascending = FAIL/critical first)
// -----------------------------------------------------------------------------

/** FAIL findings first (ascending ENUM order). */
export const FINDINGS_FAIL_FIRST = "status";
/** Highest severity first (ascending ENUM order). */
export const FINDINGS_SEVERITY_HIGH_FIRST = "severity";
/** Most recently inserted findings first. */
export const FINDINGS_RECENT_INSERT = "-inserted_at";
/** Most recently updated findings first. */
export const FINDINGS_RECENT_UPDATE = "-updated_at";

// -----------------------------------------------------------------------------
// Family B — finding-groups (integer-weighted columns, descending = first)
// -----------------------------------------------------------------------------

/** FAIL groups first (descending weighted order). */
export const FG_FAIL_FIRST = "-status";
/** Highest severity groups first (descending weighted order). */
export const FG_SEVERITY_HIGH_FIRST = "-severity";
/** New results first (descending weighted delta). */
export const FG_DELTA_NEW_FIRST = "-delta";
/** Most recently seen groups first. */
export const FG_RECENT_LAST_SEEN = "-last_seen_at";

// -----------------------------------------------------------------------------
// Family A presets (plain findings)
// -----------------------------------------------------------------------------

/**
 * Default ordering for the plain findings list. No `delta` (plain findings do
 * not expose that field); `status`/`severity` are not minus-prefixed.
 */
export const FINDINGS_DEFAULT_SORT = "status,severity,-inserted_at";
/**
 * Ordering when the API call already applies a `filter[status]`, so `status`
 * is omitted from the sort.
 */
export const FINDINGS_FILTERED_SORT = "severity,-inserted_at";
/**
 * Ordering for the "other findings" list inside the resource drawer. Uses
 * `updated_at` because the latest-findings endpoint exposes it.
 */
export const RESOURCE_DRAWER_OTHER_FINDINGS_SORT = "severity,-updated_at";

// -----------------------------------------------------------------------------
// Family B presets (finding-groups)
// -----------------------------------------------------------------------------

/** Default ordering for the finding-groups list. */
export const FINDING_GROUPS_DEFAULT_SORT =
  "-status,-severity,-delta,-last_seen_at";
/** Default ordering for the finding-group resources drill-down (same shape). */
export const FINDING_GROUP_RESOURCES_DEFAULT_SORT =
  "-status,-severity,-delta,-last_seen_at";
/**
 * Ordering for the grouped API when a status filter is already applied.
 * Omits `status` and `delta`, and must NOT contain `inserted_at`, which is not
 * a valid sort parameter on the grouped API and would cause a backend error.
